document.getElementById("app").innerHTML="\n<canvas id=\"globe\" tabindex=\"0\" role=\"img\" aria-label=\"交互式地球仪\" aria-describedby=\"globeHelp\"></canvas>\n<p id=\"globeHelp\" class=\"sr-only\">拖动或使用方向键旋转地球仪；滚轮或缩放按钮调整大小。将焦点放在地球仪上后按 Enter，可读取当前视图中心位置的信息。</p>\n\n<div class=\"topbar\">\n  <div class=\"brand\"><i>🌍</i><span class=\"t\">3D 地理地球仪</span></div>\n\n  <div class=\"group\" id=\"modes\">\n    <button class=\"b on\" data-mode=\"basic\" aria-pressed=\"true\">基础</button>\n    <button class=\"b\" data-mode=\"guide\" aria-pressed=\"false\">学习路线</button>\n    <button class=\"b\" data-mode=\"daynight\" aria-pressed=\"false\">昼夜四季</button>\n    <button class=\"b\" data-mode=\"timezone\">时区</button>\n    <button class=\"b\" data-mode=\"quiz\">练习</button>\n  </div>\n\n  <div class=\"group\" id=\"views\">\n    <button class=\"b on\" data-view=\"front\" aria-pressed=\"true\">正视图</button>\n    <button class=\"b\" data-view=\"north\" aria-pressed=\"false\">北极</button>\n    <button class=\"b\" data-view=\"south\" aria-pressed=\"false\">南极</button>\n  </div>\n  <button class=\"b\" id=\"btnLayers\" aria-expanded=\"false\" aria-controls=\"chips\">图层</button>\n\n  <div class=\"chips\" id=\"chips\"></div>\n\n  <div class=\"spacer\"></div>\n\n  <div class=\"group spin-grp\">\n    <span class=\"lbl\">转速</span>\n    <input type=\"range\" id=\"spinSpeed\" min=\"4\" max=\"120\" step=\"2\" value=\"48\" title=\"自转一圈所需秒数（越小越快）\">\n    <span class=\"val\" id=\"spinVal\">48秒/圈</span>\n  </div>\n\n  <div class=\"group\">\n    <button class=\"b\" id=\"btnSkin\" title=\"切换底色\">浅色底色</button>\n    <button class=\"b\" id=\"btnFull\" title=\"全屏 (F)\">全屏</button>\n    <a class=\"b\" id=\"btnDl\" href=\"./globe-3d.zip\" download title=\"下载离线版（地球仪 + 使用说明，断网可用）\">⤓ 下载离线版</a>\n  </div>\n</div>\n\n<div class=\"rail\">\n  <button id=\"btnZoomIn\"  title=\"放大 (+)\">＋</button>\n  <button id=\"btnZoomOut\" title=\"缩小 (−)\">−</button>\n  <div class=\"sep\"></div>\n  <button id=\"btnSpin\" class=\"on\" title=\"暂停/继续自转 (空格)\">⏸</button>\n  <button id=\"btnReset\" title=\"复位 (R)\">⟲</button>\n  <div class=\"sep\"></div>\n  <button id=\"btnShot\" title=\"导出当前画面 PNG（做 PPT 用）\">⤓</button>\n</div>\n\n<div class=\"panel\" id=\"panel\">\n  <div class=\"p-head\"><b id=\"pTitle\">模式</b><span class=\"sub\" id=\"pSub\"></span><button class=\"x\" id=\"pClose\" title=\"关闭面板 (Esc)\">×</button></div>\n  <div id=\"pBody\"></div>\n</div>\n\n<div class=\"info\" id=\"info\">\n  <div class=\"info-h\"><span class=\"pin\">📍</span><span class=\"co\" id=\"infoCo\">—</span><span class=\"tag\" id=\"infoTag\">悬停</span></div>\n  <dl id=\"infoDl\"></dl>\n</div>\n\n<div class=\"tip\">\n  拖动旋转 · 滚轮缩放 · <span class=\"kbd\">空格</span>暂停 · <span class=\"kbd\">1</span>-<span class=\"kbd\">5</span>切换模式 · <span class=\"kbd\">←→↑↓</span>微调 · <span class=\"kbd\">R</span>复位 · <span class=\"kbd\">F</span>全屏 · 点击锁定信息\n</div>\n\n<!-- 地形图例（仅在“地形”图层开启时显示） -->\n<div class=\"legend\" id=\"legend\">\n  <div class=\"t\">🏔️ <b>地形 · 海拔</b></div>\n  <div class=\"bar\" id=\"legendBar\"></div>\n  <div class=\"ticks\">\n    <span>8000m</span><span>4000</span><span>2000</span><span>1000</span>\n    <span>0 海平面</span><span>-2000</span><span>-6000</span>\n  </div>\n  <div class=\"mkey\">\n    <span style=\"color:#ff6b4a\"><i></i>山峰</span>\n    <span style=\"color:#3ea0d8\"><i></i>低地·海沟</span>\n    <span style=\"color:#ffd24a\"><i class=\"dot\"></i>地形区</span>\n  </div>\n</div>\n\n";
document.getElementById("btnDl").href=new URL("./globe-3d.zip",import.meta.url);

