  var x0 = Math.floor(fx);
  if (x0 < 0) x0 = 0; else if (x0 >= ELEV_W) x0 = ELEV_W - 1;
  var x1 = x0 + 1; if (x1 >= ELEV_W) x1 = 0;          // 经度环绕
